+    
+#ifdef	FEATURE_TEST_LINES
+    Col3 m_cnst_s_(~0);
+    Col3 m_grey_s_(~0);
+#endif
+
+    // create the minimal set, O(16*count/2)
+    for (int i = 0, index; i < 16; ++i) {
+      // check this pixel is enabled
+      int bit = 1 << i;
+      if ((pmask & bit) == 0) {
+	if ((mask & bit) == 0)
+	  m_remap[s][i] = -1;
+
+	continue;
+      }
