+    
+#ifdef	FEATURE_TEST_LINES
+    m_cnst[s] = ~m_cnst_s_.GetM8();
+    m_grey[s] = ~m_grey_s_.GetM8();
+#endif
+
+#ifdef	FEATURE_WEIGHTS_ROOTED
+    // square root the weights
+    for (int i = 0; i < m_count[s]; ++i)
